def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    threatening_bids = []
    rich_aggressive = []

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= budget * 0.6:
                    threatening_bids.append(float(bid))
                if float(bid) >= DAILY_SALARY * 0.9 and opp.get('budget', 0) > DAILY_SALARY * 4:
                    rich_aggressive.append(float(bid))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    total_players = 1 + len(alive)
    expected_share = float(supply) / float(total_players * WATER_REQ)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if expected_share < 0.4:
        urgency += 3
    elif expected_share < 0.6:
        urgency += 2
    elif expected_share < 0.9:
        urgency += 1

    if threatening_bids:
        ref_bid = max(threatening_bids)
    elif prev_bids:
        ref_bid = max(prev_bids)
    else:
        ref_bid = DAILY_SALARY * 0.6

    if urgency >= 6:
        bid = max(DAILY_SALARY * 1.02, ref_bid + 2.5)
    elif urgency >= 4:
        bid = max(DAILY_SALARY * 0.88, ref_bid + 1.2)
    elif urgency >= 2:
        bid = max(DAILY_SALARY * 0.62, ref_bid * 0.9)
    else:
        bid = DAILY_SALARY * 0.42

    if rich_aggressive and urgency < 4:
        bid = min(bid, DAILY_SALARY * 0.58)

    if supply >= 23 and urgency <= 2:
        bid = min(bid, DAILY_SALARY * 0.45)
    elif supply <= 17:
        bid = max(bid, DAILY_SALARY * 0.82)

    if budget < DAILY_SALARY * 2:
        bid = min(bid, budget * 0.55)
    elif budget < DAILY_SALARY * 4 and urgency < 4:
        bid = min(bid, DAILY_SALARY * 0.7)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 1.05))

    return max(0.0, min(float(budget), float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no one else is alive, bid conservatively
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday traces to estimate pressure
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else 0.0

    # Our urgency: if low HP or already in no-water streak, increase bid
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Supply pressure: higher supply means we can win cheaper
    # (assume price correlates with competition rather than supply, but adjust slightly)
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    supply_factor = 0.95 if supply >= supply_mid else 1.05

    # Base target: try to be around the median-ish previous pressure, but not overpay.
    # If Cindy-style pressure was extremely high, do not fully match; bid just enough to beat likely ties.
    if highest_prev_bid >= DAILY_SALARY * 1.25:
        # Cindy was aggressive; we undercut slightly
        target = max(DAILY_SALARY * 0.75, second_prev_bid + 2.0)
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(DAILY_SALARY * 0.6, highest_prev_bid * 0.85)
    else:
        target = max(DAILY_SALARY * 0.5, highest_prev_bid * 0.7)

    # Urgency adjustments
    if hp <= 2.0:
        target *= 1.25
    elif hp <= 4.0:
        target *= 1.10

    if no_water_days >= 2:
        target *= 1.15
    if no_water_days >= 4:
        target *= 1.30

    # Day-based slight escalation near end (episode_days inferred from environment not provided; use day number)
    if day >= 8:
        target *= 1.08

    # Cap by budget and keep within a reasonable range
    target *= supply_factor
    bid = min(budget, target)

    # Ensure non-negative and at least small bid if budget allows
    if bid < 0.0:
        bid = 0.0
    if bid == 0.0 and budget > 0.0:
        bid = min(budget, DAILY_SALARY * 0.1)

    return float(bid)
